from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # All users are initially online
        offline_until = [0] * numberOfUsers
        mentions = [0] * numberOfUsers

        # Prepare events with priority: OFFLINE (0) before MESSAGE (1) for the same timestamp
        processed = []
        for ev in events:
            typ = ev[0]
            t = int(ev[1])
            if typ == "OFFLINE":
                data = int(ev[2])
                priority = 0
            else:  # MESSAGE
                data = ev[2]
                priority = 1
            processed.append((t, priority, typ, data))

        # Sort by timestamp, then priority
        processed.sort(key=lambda x: (x[0], x[1]))

        for t, _, typ, data in processed:
            if typ == "OFFLINE":
                u = data
                # User becomes offline at time t, online again at t + 60
                offline_until[u] = t + 60
            else:  # MESSAGE
                tokens = data.split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if t >= offline_until[i]:
                                mentions[i] += 1
                    else:  # id<number>
                        if token.startswith("id"):
                            uid = int(token[2:])
                            mentions[uid] += 1
        return mentions
