class Solution:
    def makeStringGood(self, s: str) -> int:
        n = len(s)
        g = [0] * 26
        for ch in s:
            g[ord(ch) - 97] += 1

        INF = 10 ** 9
        ans = INF

        # K is the target frequency for each chosen letter
        for K in range(1, n + 1):
            # dp_prev[prev_inc][any_inc]
            dp_prev = [[INF, INF], [INF, INF]]
            dp_prev[0][0] = 0

            for j in range(26):
                dp_next = [[INF, INF], [INF, INF]]
                for prev_inc in (0, 1):
                    for any_inc in (0, 1):
                        cur_cost = dp_prev[prev_inc][any_inc]
                        if cur_cost == INF:
                            continue

                        # leftover from previous letter j-1
                        if j == 0:
                            leftover_prev = 0
                        else:
                            leftover_prev = g[j - 1] - (min(g[j - 1], K) if prev_inc else 0)

                        # Case: do not include letter j
                        cost_inc = leftover_prev
                        new_any = any_inc
                        if cur_cost + cost_inc < dp_next[0][new_any]:
                            dp_next[0][new_any] = cur_cost + cost_inc

                        # Case: include letter j
                        used_same = min(g[j], K)
                        deficit = K - used_same
                        used_from_prev = min(leftover_prev, deficit)
                        cost_inc = deficit + leftover_prev - used_from_prev
                        new_any = 1
                        if cur_cost + cost_inc < dp_next[1][new_any]:
                            dp_next[1][new_any] = cur_cost + cost_inc

                dp_prev = dp_next

            # Final step: handle letter 'z' (index 25)
            for inc_last in (0, 1):
                if dp_prev[inc_last][1] == INF:
                    continue
                leftover_last = g[25] - (min(g[25], K) if inc_last else 0)
                total_cost = dp_prev[inc_last][1] + leftover_last
                if total_cost < ans:
                    ans = total_cost
                    if ans == 0:
                        return 0

        return ans
